// Package: Microsoft.SemanticKernel, Microsoft.Extensions.AI, System.Text.Json

using Microsoft.SemanticKernel;
using Microsoft.Extensions.AI;
using System.Text.Json;
using System.ComponentModel;

public record AgentMessage(string Role, string Content);

public interface ISpecializedAgent
{
    Task<string> ProcessAsync(AgentMessage message, IReadOnlyList<AgentMessage> history, CancellationToken ct);
    string RoleName { get; }
}

public class ResearcherAgent : ISpecializedAgent
{
    private readonly Kernel _kernel;
    public string RoleName => "Researcher";

    public ResearcherAgent(Kernel kernel)
    {
        _kernel = kernel;
    }

    public async Task<string> ProcessAsync(AgentMessage message, IReadOnlyList<AgentMessage> history, CancellationToken ct)
    {
        var prompt = $"You are a researcher. Find facts for: {message.Content}\n" +
            "Return a concise summary with sources.";

        var arguments = new KernelArguments();
        arguments["input"] = prompt;

        var result = await _kernel.InvokePromptAsync<string>("prompt_template", arguments, ct);

        // Expected output:
        // "Research: ASP.NET Core supports dependency injection, middleware pipelines, and minimal APIs."

        return result;
    }
}

public class WriterAgent : ISpecializedAgent
{
    private readonly Kernel _kernel;
    public string RoleName => "Writer";

    public WriterAgent(Kernel kernel)
    {
        _kernel = kernel;
    }

    public async Task<string> ProcessAsync(AgentMessage message, IReadOnlyList<AgentMessage> history, CancellationToken ct)
    {
        var lastResearch = history.LastOrDefault(m => m.Role == "Researcher");
        var prompt = $"You are a writer. Draft an answer using this research: {lastResearch?.Content}\n" +
            "Original question: {message.Content}";

        var arguments = new KernelArguments();
        arguments["input"] = prompt;

        var result = await _kernel.InvokePromptAsync<string>("prompt_template", arguments, ct);

        // Expected output:
        // "ASP.NET Core provides built-in DI, middleware, and minimal APIs for backend development."

        return result;
    }
}

public class ReviewerAgent : ISpecializedAgent
{
    private readonly Kernel _kernel;
    public string RoleName => "Reviewer";

    public ReviewerAgent(Kernel kernel)
    {
        _kernel = kernel;
    }

    public async Task<string> ProcessAsync(AgentMessage message, IReadOnlyList<AgentMessage> history, CancellationToken ct)
    {
        var lastDraft = history.LastOrDefault(m => m.Role == "Writer");
        var prompt = $"You are a reviewer. Check accuracy and clarity of this draft:\n{lastDraft?.Content}\n" +
            "Return 'APPROVED' or provide corrections.";

        var arguments = new KernelArguments();
        arguments["input"] = prompt;

        var result = await _kernel.InvokePromptAsync<string>("prompt_template", arguments, ct);

        // Expected output:
        // "APPROVED - The draft is accurate and clear."

        return result;
    }
}

public class MultiAgentOrchestrator
{
    private readonly List<ISpecializedAgent> _agents;
    private readonly List<AgentMessage> _conversation = new();

    public MultiAgentOrchestrator(Kernel kernel)
    {
        _agents = new List<ISpecializedAgent>
        {
            new ResearcherAgent(kernel),
            new WriterAgent(kernel),
            new ReviewerAgent(kernel)
        };
    }

    public async Task<string> RunAsync(string userQuery, CancellationToken ct = default)
    {
        _conversation.Clear();
        var userMessage = new AgentMessage("User", userQuery);
        _conversation.Add(userMessage);

        // Route through each specialized agent in sequence
        foreach (var agent in _agents)
        {
            var response = await agent.ProcessAsync(userMessage, _conversation, ct);
            _conversation.Add(new AgentMessage(agent.RoleName, response));

            Console.WriteLine($"[{agent.RoleName}] {response}");
        }

        var finalAnswer = _conversation.Last().Content;

        // Expected final output:
        // [Researcher] Research: ASP.NET Core supports dependency injection, middleware pipelines, and minimal APIs.
        // [Writer] ASP.NET Core provides built-in DI, middleware, and minimal APIs for backend development.
        // [Reviewer] APPROVED - The draft is accurate and clear.

        return finalAnswer;
    }
}

